G=load()
def solve(I_,O_):
    H,W=I_.shape; oh,ow=O_.shape
    cnt=collections.Counter(I_.flatten().tolist()); bgn=max(cnt,key=cnt.get)
    rest=[c for c,_ in cnt.most_common()[1:]]
    info=[]
    for c_ in rest:
        lab,N=ndimage.label(I_==c_)
        szs={int(np.sum(lab==k)) for k in range(1,N+1)}
        info.append((c_,max(szs),min(szs)))
    bc,nc=(info[0][0],info[1][0]) if info[0][1]>=info[1][1] else (info[1][0],info[0][0])
    bm=ndimage.label(I_==bc)[0]
    solid=np.zeros_like(bm,dtype=bool)
    for k in range(1,bm.max()+1):
        yy,xx=np.where(bm==k); h_=int(yy.max()-yy.min()+1); w_=int(xx.max()-xx.min()+1)
        if len(yy)==h_*w_ and h_>=2 and w_>=2:
            solid[yy,xx]=True
    P=np.full((oh,ow),bgn,dtype=int)
    for i in range(oh):
        for j in range(ow):
            blk=solid[int(round(i*H/oh)):int(round((i+1)*H/oh)), int(round(j*W/ow)):int(round((j+1)*W/ow))]
            if blk.any(): P[i,j]=nc
    return P
for n in range(1,9):
    I_=np.array(G['Demo pair %d input'%n]); O_=np.array(G['Demo pair %d output'%n])
    err=int((solve(I_,O_)!=O_).sum())
    print('d%d err=%d/%d'%(n,err,O_.size))

